mapper.select:
SELECT *
FROM sessions
WHERE token_hash = #{tokenHash}
AND expires_at > #{now}
AND revoked_at IS NULL

mapper.update:
UPDATE sessions
SET expires_at = #{newExpiresAt}
WHERE token_hash = #{tokenHash}
AND revoked_at IS NULL
AND expires_at > #{now}
AND expires_at <= #{refreshThreshold}

UPDATE sessions
SET revoked_at = #{now}
WHERE token_hash = #{tokenHash}
AND revoked_at IS NULL
